    private XMLCommonInfo Info = new(new XML01());

    public string TenBenhChinh { get; private set; } = string.Empty;

    public ValidateXML01
    (
        TimePeriod officialTime,
        IXml01Repository hosoRepository,
        IEnumerable<DMYHDTICD10> DMYhct,
        IEnumerable<DMBacSi> DMBacSis,
        IEnumerable<DMKhoaBV> DMKhoaBVs,
        IEnumerable<DMChung130> DMChungs,
        Dictionary<string, string> dMDacBiets,
        Dictionary<int, string> errors,
        ILogger<dynamic>? logger = null
    ) : base(errors, logger)
    {
        _officialTime = officialTime;
        _hosoRepository = hosoRepository;
        _dmYHCT = DMYhct;
        _dmBACSI = DMBacSis;
        _dmKHOABV = DMKhoaBVs;
        _dmCHUNG = DMChungs;
        _dmDacBiet = dMDacBiets;
    }

    private static string GetLoaiRV(byte? loai)
        => loai switch
        {
            1 => "1|Ra viện",
            2 => "2|Chuyển tuyến/Chuyển cơ sở KBCB theo yêu cầu chuyên môn",
            3 => "3|Trốn viện",
            4 => "4|Xin ra viện",
            5 => "5|Chuyển tuyến/Chuyển cơ sở KBCB theo yêu cầu người bệnh",
            _ => $"{loai?.ToString() ?? "_"}|Không xác định",
        };

    private static bool Check_TheTE_ChuaDiHoc(string maThe, DateTime? ngaySinh)
    {
        if (string.IsNullOrEmpty(maThe) || !maThe.StartsWith("TE1")) return false;
        if (ngaySinh == null || !ngaySinh.HasValue) return false;

        double tuoiBN = (double)((DateTime.Now - ngaySinh.Value).Days / 365.242199);
        DateTime dMax = new DateTime(DateTime.Now.Year, 9, 30).AddDays(1);

        if (DateTime.Now.Year - ngaySinh.Value.Year <= 6)
        {
            if (tuoiBN < 6 || (tuoiBN < 7 && DateTime.Now < dMax)) return true;
        }
        else
        {
            if (tuoiBN < 6) return true;
        }

        return false;
    }

    private Evaluation<XML01, string> StrField(Expression<Func<XML01, string?>> predicate)
        => (Evaluation<XML01, string>)(object)Field(predicate);

    public async Task<bool> Validate(XML01 xml, XMLCommonInfo info)
    {
        Info = info;
        return await Validate(xml);
    }

    public override async Task<bool> Validate(XML01 xml)
    {
        // Kiem tra neu XML null thi ko chay tiep nua
        if (!await base.Validate(xml)) return false;

        try
        {
            TenBenhChinh = _dmCHUNG.FirstOrDefault(x => x.LOAI == "ICD10" && x.MA == File.MA_BENH_CHINH)?.TEN ?? "Không có thông tin bệnh";
            MsgPrefix = $"Mã BN: {File.MA_BN}; Mã CSKCB: {File.MA_CSKCB}; Mã LK: {File.MA_LK};" +
                        $"Mã ra viện: {GetLoaiRV(File.MA_LOAI_RV)}; Mã bệnh chính: {File.MA_BENH_CHINH} - {TenBenhChinh}\n";
        }
        catch
        { }

        try
        {

            #region Kiểm tra các lỗi cơ bản
            //13	XML1	MA_LK	Mã liên kết không được để trống
            //14	XML1	MA_LK	Mã liên kết không được lớn hơn 100 ký tự
            Field(x => x.MA_LK).IsEmpty().ThenError(13).LengthOver(100).ThenError(14);

            //15	XML1	STT	Số thứ tự để trống hoặc phải có giá trị từ 1 đến 999999999
            Field(x => x.STT).IsEmpty().IsOver(999999999).ThenError(15);

            //16	XML1	MA_BN	Mã bệnh nhân không được để trống
            //17	XML1	MA_BN	Mã bệnh nhân không được lớn hơn 100 ký tự
            Field(x => x.MA_BN).IsEmpty().ThenError(16).LengthOver(100).ThenError(17);

            //18	XML1	HO_TEN	Họ tên không được để trống
            //19	XML1	HO_TEN	Họ tên không được lớn hơn 255 ký tự
            Field(x => x.HO_TEN).IsEmpty().ThenError(18).LengthOver(255).ThenError(19);

            //21	XML1	SO_CCCD	Số CCCD không nhiều hơn 15 ký tự
            Field(x => x.SO_CCCD).LengthOver(15).ThenError(21);

            //2292    1   XML1 SO_CCCD[130] Số CCCD không đúng định dạng
            //Linhist changed 091026
            if (Field(x => x.SO_CCCD).NotEmpty())
            {
                RaiseError(!Uti.checkCCCD(File.SO_CCCD ?? string.Empty), 2292);
            }

            //139	XML1	NGAY_SINH	Ngày sinh không được lớn hơn thời gian hiện tại
            //140	XML1	NGAY_SINH	Ngày sinh không được lớn hơn thời gian vào viện
            Field(x => x.NGAY_SINH).IsEmpty().ThenError(20).IsOver(DateTime.Now).ThenError(139).IsOver(File.NGAY_VAO).ThenError(140);

            //20	XML1	NGAY_SINH	Ngày sinh không được để trống và phải đúng định dạng ngày tháng yyyymmddHHMM
            //Linhist changed 091026
            Field(x => x.NGAY_SINH).IsEmpty().ThenError(20);

            //22	XML1	GIOI_TINH	Giới tính không được để trống và phải là số nguyên có giá trị từ 1 đến 3
            Field(x => x.GIOI_TINH).IsEmpty().IsUnder(1).IsOver(3).ThenError(22);

            //1260	XML1	MA_QUOCTICH	Mã quốc tịch không được để trống ???
            //*** mã quốc tịch của người bệnh theo quy định tại Phụ lục 2 Thông tư số 07/2016/TT-BCA ***//
            Field(x => x.MA_QUOCTICH).IsEmpty().LengthOver(3).ThenError(1260);

            //1261	XML1	MA_DANTOC	Mã dân tộc không được để trống ???
            //*** mã quốc tịch của người bệnh theo quy định tại Phụ lục 2 Thông tư số 07/2016/TT-BCA ***//
            Field(x => x.MA_DANTOC).IsEmpty().LengthOver(2).ThenError(1261);

            //1262	XML1	MA_NGHE_NGHIEP	Mã nghề nghiệp không được để trống ???
            //*** mã nghề nghiệp theo quy định tại Quyết định số 34/2020/QĐ-TTg ngày 26 tháng 11 năm 2020 của Thủ tướng Chính phủ ***//
            // Khong co MA_NGHE_NGHIEP ghi gia tri "00000"
            //Linhist changed 250926
            // Khong co MA_NGHE_NGHIEP ghi gia tri "00"
            Field(x => x.MA_NGHE_NGHIEP).IsEmpty().LengthOver(2).ThenError(1262);

            //24	XML1	DIA_CHI	Địa chỉ không được để trống ???
            Field(x => x.DIA_CHI).IsEmpty().LengthOver(1024).ThenError(24);

            //1263	XML1	MATINH_CU_TRU	Mã tỉnh cư trú không được để trống ???
            //*** Phụ lục 1 Thông tư số 07/2016/TT-BCA ***//
            Field(x => x.MATINH_CU_TRU).IsEmpty().LengthOver(3).ThenError(1263);

            //1264	XML1	MAHUYEN_CU_TRU	Mã huyện cư trú không được để trống ???
            //*** Quyết định số 124/2004/QĐ-TTg ngày 08/7/2004 của Thủ tướng Chính phủ ***//
            Field(x => x.MAHUYEN_CU_TRU).IsEmpty().LengthOver(3).ThenError(1264);

            //1265	XML1	MAXA_CU_TRU	Mã xã cư trú không được để trống ???
            //*** Quyết định số 124/2004/QĐ-TTg ngày 08/7/2004 của Thủ tướng Chính phủ ***//
            Field(x => x.MAXA_CU_TRU).IsEmpty().LengthOver(5).ThenError(1265);

            //237	XML1	NGAY_MIEN_CCT	Ngày miễn cùng chi trả phải đúng định dạng ngày tháng yyyymmddHHMM hoặc yyyymmdd
            Field(x => x.NGAY_MIEN_CCT).NotDateTimeFormat().IgnoreEmpty().ThenError(237);

            //23	XML1	LY_DO_VV	    Lý do vào viện không được để trống
            Field(x => x.LY_DO_VV).IsEmpty().ThenError(23);

            //44	XML1	CHAN_DOAN_VAO	Chẩn đoán vào viện không được để trống
            Field(x => x.CHAN_DOAN_VAO).IsEmpty().ThenError(44);

            //45	XML1	CHAN_DOAN_RV	Chẩn đoán ra viện không được để trống
            Field(x => x.CHAN_DOAN_RV).IsEmpty().ThenError(45);

            //Linhist added 24/03/26
            //3955	XML1	CHAN_DOAN_RV	Khám sức khỏe không được thanh toán tiền BHYT
            if (!string.IsNullOrWhiteSpace(File.CHAN_DOAN_RV?.Trim()) && File.CHAN_DOAN_RV.Contains("khám sức khỏe", StringComparison.OrdinalIgnoreCase) || (File.CHAN_DOAN_RV ?? string.Empty).Contains("z00", StringComparison.OrdinalIgnoreCase))
            {
                RaiseError(3955, $"{File.CHAN_DOAN_RV} có chẩn đoán thuộc nhóm khám sức khỏe ICD10, không thanh toán Bảo hiểm Y Tế");
            }

            //37	XML1	MA_BENH_CHINH	Mã bệnh không được để trống 
            //38	XML1	MA_BENH_CHINH	Mã bệnh phải gồm từ 3 đến 7 ký tự, không được tồn tại khoảng trắng ở giữa
            //*** Kiem tra DM, co ca ma YHCT ???
            StrField(x => x.MA_BENH_CHINH).IsEmpty().ThenError(37).HasSpaceAny().LengthNotBetween(3, 7).ThenError(38);

            //*** Kiem tra DM, co ca ma YHCT ???
            StrField(x => x.MA_BENH_KT).LengthOver(100).EachCountOver(";", 12).IgnoreEmpty().ThenError(2020);

            //Linhist changed 250926
            StrField(x => x.MA_BENH_YHCT).LengthOver(150).EachCountOver(";", 13).IgnoreEmpty().ThenError(2021);

            Field(x => x.MA_PTTT_QT).LengthOver(125).IgnoreEmpty().ThenError(79);

            //35	XML1	MA_DOITUONG_KCB	Mã đối tượng KCB không được để trống
            Field(x => x.MA_DOITUONG_KCB).IsEmpty().LengthOver(4).ThenError(35);

            //2355	0	XML1	MA_DOITUONG_KCB	[130] Mã đối tượng KCB không nằm trong Danh mục
            if (!Uti.HCodeContain(File.MA_DOITUONG_KCB ?? string.Empty, ServiceConstants.MA_DOITUONG_KCB))
            {
                RaiseError(2355, $"Mã Đối tượng KCB:{File.MA_DOITUONG_KCB}, không nằm trong QĐ 2010 BYT, ngày 19/06/2025.");
            }

            if (!Uti.HCodeContain(File.MA_DOITUONG_KCB ?? string.Empty, ServiceConstants.MA_DOITUONG_KCB_3276))
            {
                RaiseError(3724, $"Mã Đối tượng KCB:{File.MA_DOITUONG_KCB}, không nằm trong QĐ 3276 BYT, ngày 17/10/2025.");
            }

            //3725    3   XML1 MA_DOITUONG_KCB    [3176] Thái Bình: Mã đối tượng KCB không thuộc Mã đối tượng KCB tại Bệnh viện quản lý
            if (!Uti.HCodeMach(File.MA_DOITUONG_KCB ?? string.Empty, ServiceConstants.MA_DOITUONG_THAI_BINH))
            {
                RaiseError(3725, $"Mã Đối tượng KCB:{File.MA_DOITUONG_KCB}, không thuộc Mã đối tượng KCB tại Bệnh viện quản lý.");
            }

            if (Field(x => x.MA_NOI_DI).NotEmpty())
            {
                //42	XML1	MA_NOI_DI	Mã nơi đi phải bao gồm 5 ký tự, không được tồn tại khoảng trắng ở giữa
                RaiseError((File.MA_NOI_DI ?? string.Empty).Length < 5, 42);

                //145	XML1	MA_NOI_DI	Mã nơi đi không được trùng với mã bệnh viện
                RaiseError(File.MA_NOI_DI == File.MA_CSKCB, 145, $"Bệnh nhân có Mã nơi đi: {File.MA_NOI_DI} trùng với Mã Bệnh viện:{File.MA_CSKCB}, Không đúng hướng dẫn 3716 và 4750, Đề nghị kiểm tra lại");

                //2498	3	XML1	GIAY_CHUYEN_TUYEN	[130] Bệnh nhân chuyển tuyến (Có mã nơi đi) nhưng chưa nhập giấy chuyển tuyến hoặc giấy hẹn khám lại
                if (Field(x => x.GIAY_CHUYEN_TUYEN).IsEmpty())
                {
                    RaiseError(2498, $"Bệnh nhân có Mã nơi đi: {File.MA_NOI_DI} (Bệnh nhân chuyển tuyến, hoặc hẹn khám lại), Nhưng không có thông tin giấy chuyển tuyến, Không đúng hướng dẫn 3716 và 4750, Đề nghị kiểm tra lại");
                }
            }

            if (Field(x => x.MA_NOI_DEN).NotEmpty())
            {
                //41	XML1	MA_NOI_DEN	Mã nơi đến phải bao gồm 5 ký tự, không được tồn tại khoảng trắng ở giữa
                RaiseError((File.MA_NOI_DEN ?? string.Empty).Length < 5, 41);

                //141	XML2	MA_NOI_DEN	Mã nơi đến không được trùng với mã bệnh viện
                RaiseError(File.MA_NOI_DEN == File.MA_CSKCB, 141, $"Bệnh nhân có Mã nơi đến: {File.MA_NOI_DEN} trùng với mã CSKCB: {File.MA_CSKCB} , Không đúng hướng dẫn 3716 và 4750, Đề nghị kiểm tra lại");
            }

            //146	XML1	MA_TAI_NAN	Mã tai nạn phải có giá trị từ 0 đến 8 hoặc để trống
            //Linhist changed 250926
            Field(x => x.MA_TAI_NAN).NotBetweenOrEqual(0, 8).IgnoreEmpty().ThenError(146);

            //43	XML1	NGAY_VAO	Ngày vào không được để trống và phải đúng định dạng ngày tháng yyyymmddHHMM
            //147	XML1	NGAY_VAO	Ngày vào không được lớn hơn thời gian hiện tại
            Field(x => x.NGAY_VAO).IsEmpty().ThenError(43).IsOver(DateTime.Now).ThenError(147);

            //47	XML1	NGAY_RA	Ngày ra không được để trống và phải đúng định dạng ngày tháng yyyymmddHHMM
            Field(x => x.NGAY_RA).IsEmpty().ThenError(47);

            //148	XML1	NGAY_RA	Ngày ra không lớn hơn thời gian hiện tại
            if (Field(x => x.MA_LOAI_KCB).NotValue("02", "07", "05"))
            {
                Field(x => x.NGAY_RA).IsOver(DateTime.Now).ThenError(148);
            }

            //149	XML1	NGAY_RA	Ngày ra không được nhở hơn thời gian vào
            Field(x => x.NGAY_RA).IsUnder(File.NGAY_VAO).ThenError(149);

            if (Field(x => x.NGAY_VAO_NOI_TRU).NotEmpty())
            {
                if (File.NGAY_VAO_NOI_TRU != DateTime.MinValue || File.NGAY_VAO_NOI_TRU.Value.Year != 1753)
                {
                    //2387	3	XML7	NGAY_RA	[130] Ngày ra không được nhỏ hơn ngày vào nội trú
                    RaiseError(File.NGAY_RA < File.NGAY_VAO_NOI_TRU,
                        2387, $"Bệnh nhân có Ngày ra viện: {File.NGAY_RA:yyyyMMdd} < Ngày vào nội trú: {File.NGAY_VAO_NOI_TRU:yyyyMMdd:hhmm}, Không hợp lý về mặt logic thời gian, Đề nghị kiểm tra lại");

                    //2458	3	XML1	NGAY_VAO	[130] Ngày vào không được nhỏ hơn ngày vào nội trú
                    RaiseError(File.NGAY_VAO > File.NGAY_VAO_NOI_TRU && File.MA_LOAI_KCB == "03" && File.NGAY_VAO_NOI_TRU != null,
                        2458, $"Bệnh nhân có Ngày vào viện: {File.NGAY_VAO:yyyyMMdd} > Ngày vào nội trú: {File.NGAY_VAO_NOI_TRU:yyyyMMdd:hhmm}, Không hợp lý về mặt logic thời gian, Đề nghị kiểm tra lại");
                }
            }

            //2022    XML1    GIAY_CHUYEN_TUYEN   Giấy chuyển tuyến không được vượt quá 50 ký tự hoặc để trống
            Field(x => x.GIAY_CHUYEN_TUYEN).LengthOver(50).IgnoreEmpty().ThenError(2022);

            //50	XML1	KET_QUA_DTRI	Kết quả điểu trị không được để trống và phải là số nguyên có giá trị từ 1 đến 8
            Field(x => x.KET_QUA_DTRI).Not_KQ_DTRI().ThenError(50);

            //51	XML1	MA_LOAI_RV	Tình trạng ra viện không được để trống và phải là số nguyên có giá trị từ 1 đến 5
            Field(x => x.MA_LOAI_RV).Not_LOAI_RV().ThenError(51);

            //52	XML1	NGAY_TTOAN	Ngày thanh toán phải đúng định dạng ngày tháng yyyymmddHHMM hoặc để trống
            //153	XML1	NGAY_TTOAN	Ngày thanh toán không được lớn hơn thời gian hiện tại
            Field(x => x.NGAY_TTOAN).NotDateTimeFormat().IsEmpty().ThenError(52);

            //152	XML1	NGAY_TTOAN	Ngày thanh toán không được nhỏ hơn ngày ra viện
            if (!Field(x => x.MA_LOAI_KCB).HasValue("02", "05", "07"))
            {
                Field(x => x.NGAY_TTOAN).NotDateTimeFormat().IsUnder(Field(x => x.NGAY_RA)).ThenError(152);
            }

            //Linhist changed 091026 - bỏ NotNumberFormat() trong IsEmpty đã có

            ////62	XML1	T_TONGCHI_BH	Tổng chi BH phải là số thập phân lớn hơn hoặc bằng 0 và làm tròn đến 2 đơn vị thập phân (phân cách bởi dấu '.') hoặc để trống

            Field(x => x.T_THUOC).IsEmpty().IsUnder(0).ThenError(2025);

            Field(x => x.T_VTYT).IsEmpty().IsUnder(0).ThenError(59);

            Field(x => x.T_TONGCHI_BV).IsEmpty().IsUnderOrEqual(0).ThenError(61);

            //62	XML1	T_TONGCHI_BH	Tổng chi BH phải là số thập phân lớn hơn hoặc bằng 0 và làm tròn đến 2 đơn vị thập phân (phân cách bởi dấu '.') hoặc để trống
            Field(x => x.T_TONGCHI_BH).NotNumberFormat().IsUnder(0).ThenError(62);

            Field(x => x.T_BNTT).IsEmpty().IsUnder(0).ThenError(63);

            Field(x => x.T_BNCCT).IsEmpty().IsUnder(0).ThenError(64);

            Field(x => x.T_NGUONKHAC).IsEmpty().IsUnder(0).ThenError(67);

            Field(x => x.T_BHTT_GDV).IsEmpty().IsUnder(0).ThenError(68);

            //70	XML1	NAM_QT	Năm quyết toán không được để trống và phải là số nguyên lớn hơn 2000
            Field(x => x.NAM_QT).IsEmpty().IsUnder(2000).ThenError(70);

            //71	XML1	THANG_QT	Tháng quyết toán không được để trống và phải là số nguyên có giá trị từ 1 đến 12
            //08/09/2025 không hiểu sao tự nhiên phát sinh lỗi Null obbject, cần kiểm tra thêm
            RaiseError(File.THANG_QT == null || File.THANG_QT < 1 || File.THANG_QT > 12, 71);

            //75	XML1	MA_KHOA	Mã khoa không được để trống
            //74	XML1	MA_KHOA	Mã khoa không được lớn hơn 50 ký tự
            Field(x => x.MA_KHOA).IsEmpty().ThenError(75).LengthOver(50).ThenError(74);

            //76	XML1	MA_CSKCB	Mã CSKCB không được để trống
            //77	XML1	MA_CSKCB	Mã CSKCB phải gồm 5 ký tự, không tồn tại khoảng trắng ở giữa
            Field(x => x.MA_CSKCB).IsEmpty().ThenError(76).LengthNotEqual(5).HasSpaceAny().ThenError(77);

            //78	XML1	MA_KHUVUC	Mã khu vực để trống hoặc phải có giá trị là K1, K2, K3
            if (Field(x => x.MA_KHUVUC).NotEmpty())
            {
                RaiseError(!Uti.CodeMatch(File.MA_KHUVUC ?? string.Empty, "K1;K2;K3"), 78);
            }

            //2393	4	XML1	CAN_NANG	[130] Cân năng không để bằng 0
            //4002	3	XML1	CAN_NANG	[3176] Cân nặng đang để quá 200kg, đề nghị kiểm tra lại
            Field(x => x.CAN_NANG).IsEmpty().IsUnderOrEqual(0).ThenError(80).HasValue(0).ThenError(2393).IsOver(200).ThenError(4002);

            Field(x => x.CAN_NANG_CON).LengthOver(100).ThenError(2027);

            //72	XML1	MA_HSBA	Mã hồ sơ bệnh án không được để trống ???
            Field(x => x.MA_HSBA).IsEmpty().LengthOver(100).ThenError(72);

            #endregion

            #region Update code từ 4210 qua
            //3796	3	XML1	MA_DOITUONG_KCB	[Bắc Ninh CDC] Mã đối tượng KCB không nằm trong phạm vi của Đơn vị
            RaiseError(File.MA_DOITUONG_KCB != "1.1" && File.MA_DOITUONG_KCB != "1.2",
                3796, $"Bệnh nhân có mã đối tượng KCB:{File.MA_DOITUONG_KCB}, không nằm trong phạm vi KCB của Bệnh viện, kiểm tra lại");

            //3785	3	XML1	NGAY_TTOAN	[3176] Ngày thanh toán đang lớn hơn ngày tạo, kiểm tra lại
            if (File.NGAY_LAP != null && File.NGAY_TTOAN != null && File.NGAY_LAP < File.NGAY_TTOAN)
            {
                RaiseError(3785, $"Bệnh nhân khởi tạo hồ sơ đề nghị thanh toán vào lúc: {File.NGAY_LAP.Value.ToString("dd/MM/yyyy HH:mm")}, tuy nhiên ngày Thanh toán lại là: {File.NGAY_TTOAN.Value.ToString("dd/MM/yyyyy HH:mm")} không hợp lý đề nghị kiểm tra lại");
            }

            //3845	3	XML1	MA_DOITUONG_KCB	[3176] Mã đối tượng KCB không phù hợp theo Quyết định 3276/QĐ-BYT 2025
            //Linhist changed 211026
            if ((File.MA_DOITUONG_KCB == "1.3" && ((File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB) || string.IsNullOrEmpty(File.GIAY_CHUYEN_TUYEN))) ||
                ((File.MA_DOITUONG_KCB == "1.4" || File.MA_DOITUONG_KCB == "1.11") && (File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB)) ||
                (File.MA_DOITUONG_KCB == "1.5" && ((File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB) || string.IsNullOrEmpty(File.GIAY_CHUYEN_TUYEN))) ||
                (File.MA_DOITUONG_KCB == "1.7" && Info.NGAY_TUOI_BN > 28))
            {
                RaiseError(3845, $"Bệnh nhân có mã Đăng ký KCB: {File.MA_CSKCB} và Mã Đăng ký Ban đầu: {File.MA_DKBD} trùng nhau, Mã đối tượng KCB: {File.MA_DOITUONG_KCB} không đúng với hướng dẫn tại QĐ 3276/QĐ-BYT năm 2025");
            }
            if (File.MA_DOITUONG_KCB == "1.1" && !(File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB))
            {
                RaiseError(3845, $"Bệnh nhân có mã Đăng ký KCB: {File.MA_CSKCB} và Mã Đăng ký Ban đầu: {File.MA_DKBD} khác nhau, Mã đối tượng KCB: {File.MA_DOITUONG_KCB} không đúng với hướng dẫn tại QĐ 3276/QĐ-BYT năm 2025");
            }
            if ((File.MA_DOITUONG_KCB == "1.13" || File.MA_DOITUONG_KCB == "1.14") && ((File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB) || !"01;02;05;08".Contains(File.MA_LOAI_KCB ?? string.Empty)))
            {
                RaiseError(3845, $"Bệnh nhân tự đến KCB ngoại trú tại cơ sở KCB cấp cơ bản, Mã Đăng ký KCB: {File.MA_CSKCB} và Mã Đăng ký Ban đầu: {File.MA_DKBD}, Mã đối tượng KCB: {File.MA_DOITUONG_KCB}, Mã Loại KCB: {File.MA_LOAI_KCB}, đề nghị kiểm tra lại tại QĐ 3276/QĐ-BYT năm 2025");
            }
            if (File.MA_DOITUONG_KCB == "1.15" && ((File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB) || !"03;04;09".Contains(File.MA_LOAI_KCB ?? string.Empty)))
            {
                RaiseError(3845, $"Bệnh nhân tự đến KCB nội trú tại cơ sở KCB cấp cơ bản, Mã Đăng ký KCB:{File.MA_CSKCB} và Mã Đăng ký Ban đầu: {File.MA_DKBD}, Mã đối tượng KCB: {File.MA_DOITUONG_KCB} , Mã Loại KCB: {File.MA_LOAI_KCB}, đề nghị kiểm tra lại tại QĐ 3276/QĐ-BYT năm 2025");
            }

            //Linhist added 220926
            //3845	3	XML1	MA_DOITUONG_KCB	[3176] Mã đối tượng KCB không phù hợp theo Quyết định 3276/QĐ-BYT 2025
            //Linhist changed 131026
            if (File.MA_DOITUONG_KCB == "1.16" && ((File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB) || !Uti.CodeMatch(File.MA_BENH_CHINH ?? string.Empty, MA_BENH_PL2_TT01_2025)))
            {
                RaiseError(3845, $"Bệnh nhân tự đến KCB tại cơ sở KCB cấp cơ bản đối với các bệnh thuộc PL2/ TT01, Mã CSKCB: {File.MA_CSKCB}, Mã Đăng ký BD: {File.MA_DKBD}, Mã Bệnh Chính: {File.MA_BENH_CHINH} không đúng với hướng dẫn tại QĐ 3276/QĐ-BYT năm 2025");
            }    

            //Linhist changed 170926 - đổi thành 3845
            //3846	3	XML1	MA_DOITUONG_KCB	[3176] Thái Bình: Mã đối tượng KCB không phù hợp theo Quyết định 3276/QĐ-BYT 2025
            if ((File.MA_DOITUONG_KCB == "3.1" || File.MA_DOITUONG_KCB == "3.2" || File.MA_DOITUONG_KCB == "3.3" || File.MA_DOITUONG_KCB == "3.6") && (File.MA_DKBD ?? string.Empty).StartsWith(File.MA_CSKCB))
            {
                RaiseError(3845, $"Bệnh nhân có mã Đăng ký KCB: {File.MA_CSKCB} và Mã Đăng ký Ban đầu: {File.MA_DKBD} trùng nhau, Mã đối tượng KCB: {File.MA_DOITUONG_KCB} không đúng với hướng dẫn tại QĐ 3276/QĐ-BYT năm 2025");
            }

            if (File.MA_LOAI_KCB == "01" && File.NGAY_RA != null && File.NGAY_VAO != null && File.NGAY_RA.Value.Date != File.NGAY_VAO.Value.Date)
            {
                RaiseError(3776, $"Bệnh nhân khám bệnh, có Mã Loại KCB: {File.MA_LOAI_KCB}, có ngày vào viện: {File.NGAY_VAO.Value.ToString("dd/MM/yyyy HH:mm")}, ngày ra viện: {File.NGAY_RA.Value.ToString("dd/MM/yyyy HH:mm")} là không hợp lý, đề nghị kiểm tra lại");
            }

            //3342    3   XML1 MA_BENH_CHINH[3176] Bắc Giang: Kê giường hồi sức cấp cứu cho Bệnh nhân Nội trú chưa phù hợp với mức độ, trình trạng bệnh
            if (File.MA_LOAI_KCB == "03" && Uti.HCodeContain(File.MA_BENH_CHINH ?? string.Empty, BENH_NHE_KO_CC) && File.XML03s.Any(x => Uti.HCodeContain(x.MA_DICH_VU ?? string.Empty, GIUONG_HSCC)))
            {
                RaiseError(3342, "Bệnh thuộc nhóm bệnh nhẹ kê giường hồi sức cấp cứu (Chuyên đề Bảo hiểm KT35). Vui lòng kiểm tra lại.");
            }

            if (Uti.HCodeContain(File.MA_LOAI_KCB ?? string.Empty, "07") && File.XML03s.Any(x => x.MA_NHOM == 13))
            {
                RaiseError(3328, "Bệnh nhân này đến nhận thuốc theo lịch hẹn (Mã Loại KCB=7) nên không được phát sinh công khám (Căn cứ quyết định 824/QĐ BYT ngày 15/02/2023.");
            }

            RaiseError((File.MA_BENH_KT ?? string.Empty).Contains("Z00"),
                3732, $"{File.MA_BENH_KT}, có mã Bệnh Z00 thuộc nhóm bệnh khám nghĩa vụ quân sự, không thanh toán Bảo hiểm Y Tế");

            //418 Hồ sơ khám sức khỏe không được thanh toán BHYT
            RaiseError(Uti.HCodeContain(File.MA_BENH_CHINH ?? string.Empty, "Z00.*;Z01.*;Z02.*;Z10.0;Z10.1"),
                418, $"{File.MA_BENH_CHINH} thuộc nhóm bệnh đi khám sức khỏe ICD10, không thanh toán Bảo hiểm Y Tế");

            //3283	4	XML1	MA_BENH_CHINH	[3176] Chi phí đề nghị TT ngoài phạm vi chi trả BHYT (của HSBA có mã chẩn đoán) Z30 theo Luật BHYT 2008
            RaiseError(Uti.CodeContain(File.MA_BENH_CHINH ?? string.Empty, "Z30.*"),
                3283, $"Chi phí đề nghị thanh toán cho Bệnh nằm ngoài phạm vi chi trả BHYT. Căn cứ Luật bảo hiểm y tế năm 2018");

            //3284	4	XML1	MA_BENH_CHINH	[3176]  Sử dụng kỹ thuật hỗ trợ sinh sản, dịch vụ kế hoạch hóa gia đình, nạo hút thai, phá thai ngoài phạm vi thanh toán của BHYT
            RaiseError(Uti.CodeContain(File.MA_BENH_CHINH ?? string.Empty, "Z31.*;O04.4;O05.2;O05.3;O05.4;O05.9;O06.2;O06.3;O06.4;O06.8;O06.9;O07.2;O07.4;O07.9"),
                3284, $"Sử dụng kỹ thuật hỗ trợ sinh sản, dịch vụ kế hoạch hóa gia đình, nạo hút thai, phá thai ngoài phạm vi thanh toán của BHYT. Căn cứ Luật bảo hiểm y tế năm 2018");

            //2506	3	XML1	MA_LOAI_KCB	[130] Bệnh nhân có thực hiện dịch vụ >1 ngày từ thời điểm thực hiện Y Lệnh, kiểm tra xem đi Khám bệnh hay Ngoại trú
            if (File.MA_LOAI_KCB == "01")
            {
                var xml03Infor = File.XML03s.FirstOrDefault(x => x.NGAY_KQ != null && x.NGAY_YL != null && x.NGAY_KQ.HasValue && x.NGAY_YL.HasValue && x.NGAY_YL.Value.Date < x.NGAY_KQ.Value.Date);
                if (xml03Infor != null)
                {
                    RaiseError(2506, $"Bệnh nhân có sử dụng dịch vụ: {xml03Infor.MA_DICH_VU} - {xml03Infor.TEN_DICH_VU} có thời gian y lệnh là: {xml03Infor.NGAY_YL:dd/MM/yyyy}, " +
                            $"thời gian trả kết quả {xml03Infor.NGAY_KQ:dd/MM/yyyy}, vậy thời gian thực hiện là: {(xml03Infor.NGAY_KQ.GetValueOrDefault().Date - xml03Infor.NGAY_YL.GetValueOrDefault().Date).Days} ngày là không phù hợp, Đề nghị kiểm tra lại"
                        );
                }
            }

            //1241	1	XML1	KET_QUA_DTRI	Điều trị ngoại trú không được phép kết quả ra viện là Khỏi
            if (Uti.HCodeContain(File.MA_LOAI_KCB ?? string.Empty, "01;02;05;07;08") && File.KET_QUA_DTRI == 1)
            {
                RaiseError(1241, $"Bệnh nhân đến khám bệnh, với các bệnh Mãn tính như Tiểu Đường, Tăng Huyết Áp, hoặc mới khám bệnh chưa dùng thuốc. kết quả điều trị KHỎI là không phù hợp, Đề nghị kiểm tra lại");
            }

            //1227  1   XML1    MA_BENH     Điều trị nội trú không cần thiết: Bệnh nhẹ mà vào điều trị Nội Trú
            if (Uti.HCodeContain(File.MA_LOAI_KCB ?? string.Empty, "03;04") && Uti.CodeMatch(File.MA_BENH_CHINH ?? string.Empty, BENH_NHE_KO_NT))
            {
                RaiseError(1227, $"Chuyên đề Bảo hiểm: Kiểm tra lại Bệnh {TenBenhChinh} cho điều trị nội trú có hợp lý không? Đề nghị kiểm tra lại");
            }

            //1987	0	XML1	MA_KHOA	Mã khoa nằm ngoài danh mục được Bảo hiểm phê dyệt
            //*** Thêm Danh Mục Khoa

            //4115	3	XML1	MA_BENH_CHINH	[ĐKQT Hải Phòng] Mã bệnh không thuộc phạm vi thanh toán BHYT
            if (File.MA_CSKCB == "31313")
            {
                RaiseError(Uti.CodeContain(File.MA_BENH_CHINH ?? string.Empty, MA_BENH_SAI_31313) || Uti.CodeContain(File.MA_BENH_KT ?? string.Empty, MA_BENH_SAI_31313),
                    4115, $"Mã bệnh chính: {File.MA_BENH_CHINH}, có mã Bệnh không thuộc phạm vi thanh toán BHYT");
            }

            //23	23	0	XML1	LY_DO_VV	Lý do vào viện không được để trống
            RaiseError(string.IsNullOrEmpty(File.LY_DO_VV?.Trim()),
                23, $"Lý do vào viện không được để trống");

            //2323	0	XML1	MA_QUOCTICH	[130] Mã quốc tịch không nằm trong Danh mục phê duyệt
            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "QT" && x.MA == File.MA_QUOCTICH), 2323);

            //2324	0	XML1	MA_NGHE_NGHIEP	[130] Mã nghề nghiệp ko nằm trong danh mục phê duyệt
            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "NNG" && x.MA == File.MA_NGHE_NGHIEP), 2324);

            //2325    0   XML1 MATINH_CU_TRU[130] Mã tỉnh cư trú không nằm trong Danh mục
            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "TINH" && x.MA == File.MATINH_CU_TRU), 2325);

            //2326    0   XML1 MAHUYEN_CU_TRU[130] Mã huyện cứ trú không có trong danh mục
            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "HUYEN" && x.MA == File.MAHUYEN_CU_TRU), 2326);

            //2340	0	XML1	MAXA_CU_TRU	[130] Mã xã cư trú không có trong Danh mục phê duyệt
            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "XA" && x.MA == File.MAXA_CU_TRU), 2340);

            //2673	3	XML1	MA_NGHE_NGHIEP	[3176] Mã nghề nghiệp không đúng trong Danh mục Phê duyệt
            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "NNG3176" && x.MA == File.MA_NGHE_NGHIEP), 2673);

            //49	XML1	SO_NGAY_DTRI	Số ngày điều trị không được để trống và phải là số nguyên có giá trị từ 0 đến 999
            Field(x => x.SO_NGAY_DTRI).IsEmpty().NotBetweenOrEqual(0, 999).ThenError(49);

            //2675	3	XML1	DU_PHONG	[3176] Thông tin chiều cao bắt buộc phải nhập
            Field(x => x.DU_PHONG).IsEmpty().ThenError(2675);

            //2676    3   XML1 DU_PHONG[3176] Giá trị nhập có vấn đề, đề nghị kiểm tra lại
            RaiseError(!double.TryParse(File.DU_PHONG ?? "", out double chieucao) || (chieucao < 0 || chieucao > 250), 2676);
            #endregion

            #region Kiểm tra các lỗi liên quan đến tiền (có tính toán)
            var tongThuoc = 0m;
            var tongVTYT = 0m;
            var tongDV_VT = 0m;
            var tongBH = 0m;
            var tongBNTT = 0m;
            var tongBNCCT = 0m;
            var tongNgKhac = 0m;
            var tongGVT = 0m;

            try
            {
                foreach (var x2 in File.XML02s)
                {
                    tongThuoc += (decimal?)x2.THANH_TIEN_BV ?? 0m;
                    tongBH += (decimal?)x2.THANH_TIEN_BH ?? 0m;
                    tongBNTT += (decimal?)x2.T_BNTT ?? 0m;
                    tongBNCCT += (decimal?)x2.T_BNCCT ?? 0m;
                    tongNgKhac += (decimal?)x2.T_NGUONKHAC ?? 0m;

                    if (x2.MA_PTTT != null && x2.MA_PTTT == 1)
                    {
                        tongGVT += (decimal?)x2.T_BHTT ?? 0m;
                    }
                }

                foreach (var x3 in File.XML03s)
                {
                    tongDV_VT += (decimal?)x3.THANH_TIEN_BV ?? 0m;
                    if (x3.MA_NHOM == 10 || x3.MA_NHOM == 11)
                    {
                        tongVTYT += (decimal?)x3.THANH_TIEN_BV ?? 0m;
                    }

                    tongBH += (decimal?)x3.THANH_TIEN_BH ?? 0m;
                    tongBNTT += (decimal?)x3.T_BNTT ?? 0m;
                    tongBNCCT += (decimal?)x3.T_BNCCT ?? 0m;
                    tongNgKhac += (decimal?)x3.T_NGUONKHAC ?? 0m;

                    if (x3.MA_PTTT != null && x3.MA_PTTT == 1)
                    {
                        tongGVT += (decimal?)x3.T_BHTT ?? 0m;
                    }
                }
            }
            catch (Exception ex)
            {
                WriteLog($"Validate130: Lỗi check Tiền: MaBN: {File.MA_BN} MaCSKCB: {File.MA_CSKCB}, MABN: {File.MA_BN} XML1 Giám định có lỗi: {ex.ToString()} [{DateTime.Now:dd/MM hh:mm:ss}]", nameof(ValidateXML01));
            }

            //2179   4   XML1 T_THUOC[130] Tiền thuốc không bằng tổng tiền thuốc trong XML2
            RaiseError(!Uti.IsEqualUp(tongThuoc, (decimal?)File.T_THUOC),
                2179, $"Bệnh nhân có Tiền thuốc tại XML1: {File.T_THUOC:N2}  khác với Tính tổng tiền thuốc tại XML2: {tongThuoc:N2}, Đề nghị kiểm tra lại");

            //2180    4   XML1 T_VTYT[130] Tiền VTYT không bằng tổng tiền VTYT trong XML3
            RaiseError(!Uti.IsEqualUp(tongVTYT, (decimal?)File.T_VTYT),
                2180, $"Bệnh nhân có Tiền VTYT tại XML1: {File.T_VTYT:N2}  khác với Tính tổng tiền Vật tư tại XML3: {tongVTYT:N2}, Đề nghị kiểm tra lại");

            //2181    4   XML1 T_TONGCHI_BV[130] Tổng chi BV không bằng tổng tiền thuốc và VTYT trong XML2 và XML3
            RaiseError(!Uti.IsEqualUp(tongThuoc + tongDV_VT, (decimal?)File.T_TONGCHI_BV),
                2181, $"Bệnh nhân có Tổng chi BV tại XML1: {File.T_TONGCHI_BV:N2}  khác với mức tính Tổng chi tại XML2,3: {(tongThuoc + tongDV_VT):N2}, Đề nghị kiểm tra lại");

            //2182    4   XML1 T_TONGCHI_BH[130] Tổng chi BH không bằng tổng tiền thuốc và VTYT trong XML2 và XML3
            RaiseError(!Uti.IsEqualUp(tongBH, (decimal?)File.T_TONGCHI_BH),
                2182, $"Bệnh nhân có Tổng chi BH tại XML1: {File.T_TONGCHI_BH:N2}  khác với mức tính Tổng chi BH tại XML2,3: {(tongBH):N2}, Đề nghị kiểm tra lại");

            //2183    4   XML1 T_BNTT[130] Tiền BNTT không bằng tổng tiền T_BNTT trong XML2 & XML3
            RaiseError(!Uti.IsEqualUp(tongBNTT, (decimal?)File.T_BNTT),
                2183, $"Bệnh nhân có Tổng Bệnh nhân TT tại XML1: {File.T_BNTT:N2}  khác với mức tính Tổng Bệnh nhân TT tại XML2,3: {(tongBNTT):N2}, Đề nghị kiểm tra lại");

            //2184    4   XML1 T_BNCCT[130] Tiền BNCCT không bằng tổng tiền T_BNCCT trong XML2 & XML3
            RaiseError(!Uti.IsEqualUp(tongBNCCT, (decimal?)File.T_BNCCT),
                2184, $"Bệnh nhân có Tổng Bệnh nhân CCT tại XML1: {File.T_BNCCT:N2}  khác với mức tính Tổng Bệnh nhân CCT tại XML2,3: {(tongBNCCT):N2}, Đề nghị kiểm tra lại");

            //2185    4   XML1 T_NGUONKHAC[130] Tiền nguồn khác không bằng tổng tiền T_NGUONKHAC trong XML2 &XML3
            RaiseError(!Uti.IsEqualUp(tongNgKhac, (decimal?)File.T_NGUONKHAC),
                2185, $"Bệnh nhân có Tổng Nguồn khác tại XML1: {File.T_NGUONKHAC:N2}  khác với mức tính Tổng Nguồn khác tại XML2,3: {(tongNgKhac):N2}, Đề nghị kiểm tra lại");

            //65	XML1	T_BHTT	Tiền bảo hiểm thanh toán không được để trống và phải là số thập phân lớn hơn hoặc bằng 0 và làm tròn đến 2 đơn vị thập phân (phân cách bởi dấu '.'
            Field(x => x.T_BHTT).IsEmpty().NotNumberFormat().IsUnder(0).ThenError(65);

            if (File.T_TONGCHI_BH != null && File.T_BNCCT != null)
            {
                var tongBHTT = Uti.RoundUp((decimal)File.T_TONGCHI_BH - (decimal)File.T_BNCCT);
                RaiseError(!Uti.IsEqualUp(tongBHTT, (decimal?)File.T_BHTT),
                    2026, $"Bệnh nhân có Tổng BHTT tại XML1: {File.T_BHTT:N2}  khác với mức tính Tổng BHTT tại XML2,3: {(tongBHTT):N2}, Đề nghị kiểm tra lại");
            }
            #endregion

            #region Chuyên đề bảo hiểm BHXH Việt Nam
            //4046	4	XML1	MA_LOAI_KCB	[3176] Chuyên đề Bảo hiểm KT144: Không thanh toán DVKT tiêm bắp, tiêm tĩnh mạch, truyền tĩnh mạch, tháo bột, cắt chỉ, thay băng trong điều trị nội trú
            //Linhist changed 16/07/26
            if ((File.MA_LOAI_KCB == "03" || File.MA_LOAI_KCB == "09") && File.XML03s.Any(x => Uti.HCodeContain(x.MA_DICH_VU ?? string.Empty, "15.0303.0200;10.9003.0200;10.9003.0200_BS;03.3911.0200;07.0225.0200")))
            {
                RaiseError(true,
                    4046, $"Hồ sơ có chứa dịch vụ kỹ thuật thuộc danh mục DVKT tiêm bắp, tiêm tĩnh mạch, truyền tĩnh mạch, tháo bột, cắt chỉ, thay băng trong điều trị nội trú theo chuyên đề Bảo hiểm KT144 của BHXH Việt Nam, đề nghị kiểm tra lại");
            }
            #endregion

            #region Kiểm tra các lỗi có liên quan đến các trường khác
            //1299 	1	XML1	NGAY_VAO	Bệnh nhân không cấp cứu vào Viện ngoài giờ hành chính
            if (File.MA_DOITUONG_KCB != "2" && _officialTime != null && _officialTime.IsValid)
            {
                RaiseError(!_officialTime.InRange(File.NGAY_VAO),
                    1299, $"Bệnh nhận vào viện {File.NGAY_VAO:dd/MM/yyyy HH:mm}, Giờ đăng ký khám của Viện là: {_officialTime}");
            }

            //1982	3	XML3	SO_LUONG	BV ĐK Quốc Tế Hải Phòng không kê giường lẻ theo TT39
            if (File.MA_CSKCB == "31313")
            {
                var allNgayGiuong = File.XML03s.Where(x => Uti.NumExists(x.MA_NHOM, 14, 15) && x.SO_LUONG != null);
                if (allNgayGiuong != null && allNgayGiuong.Any())
                {
                    var sumNgayGiuong = allNgayGiuong.Sum(x => x.SO_LUONG) ?? 0d;
                    if (sumNgayGiuong % 1d != 0d)
                    {
                        var lastNgayGiuong = allNgayGiuong.Where(x => x.NGAY_YL != null).OrderByDescending(x => x.NGAY_YL).FirstOrDefault();
                        RaiseError(lastNgayGiuong != null, 1982);
                    }
                }
            }

            // Ket qua dieu tri KET_QUA_DTRI theo 3176
            //MA_LOAI_RV theo 3176
            //                -Mã "5": Chuyển tuyến/Chuyển cơ sở KBCB theo yêu cầu người bệnh.

            // Trích dẫn TT39-BYT-2024 Điều 4c
            // Số ngày điều trị nội trú bằng ngày ra viện trừ (-) ngày vào viện cộng (+) 1: áp dụng đối với các trường hợp:
            if (File.NGAY_RA != null && File.NGAY_VAO != null && File.NGAY_VAO_NOI_TRU != null)
            {
                var tongGioDtri = (decimal)(File.NGAY_RA.Value - File.NGAY_VAO.Value).TotalHours; //210 / 24 = 8.75
                var tongNgayDtri = (int)(File.NGAY_RA.Value.Date - File.NGAY_VAO.Value.Date).TotalDays; //9
                var tongNgayDtri3176 = (int)((File.NGAY_RA?.Date - File.NGAY_VAO_NOI_TRU?.Date)?.TotalDays ?? 0); //209
                var tongGioDtri3716 = (int)((File.NGAY_RA?.Date - File.NGAY_VAO_NOI_TRU?.Date)?.TotalHours ?? 0); // 9

                if (File.MA_LOAI_KCB == "03")
                {
                    var ngayGiuong = 0;
                    var ngayGuuong3176 = 0;
                    if (tongGioDtri >= 4m && tongGioDtri <= 24m)
                    {
                        ngayGiuong = 1;
                    }
                    else if (((File.KET_QUA_DTRI == 5 || File.KET_QUA_DTRI == 4) && (File.MA_LOAI_RV == 4 || File.MA_LOAI_RV == 5 || File.MA_LOAI_RV == 2)) ||
                            (File.MA_LOAI_RV == 2 || File.MA_LOAI_RV == 5) || (File.KET_QUA_DTRI == 5))
                    {
                        ngayGiuong = tongNgayDtri + 1;
                        ngayGuuong3176 = tongNgayDtri3176 + 1;
                    }
                    else
                    {
                        ngayGiuong = tongNgayDtri;
                        ngayGuuong3176 = tongNgayDtri3176;
                    }

                    var allGiuongs = File.XML03s.Where(x => x.MA_NHOM == 14 || x.MA_NHOM == 15);
                    var sumGiuongs = allGiuongs.Any() ? allGiuongs.Sum(x => (decimal?)x.SO_LUONG) : 0m;
                    var sumNgayGiuong = (int)Uti.RoundUp(sumGiuongs, 0); //10

                    var msg = $"Bệnh nhân kế quả điều trị: {File.KET_QUA_DTRI}|{ServiceConstants.GetValue(ServiceConstants.ketquadieutri, File.KET_QUA_DTRI.ToString())}" +
                            $"và có Tình trạng ra Viện: {File.MA_LOAI_RV}|{ServiceConstants.GetValue(ServiceConstants.Loairavien, File.MA_LOAI_RV.ToString())}\n" +
                            $"Vào viện: {File.NGAY_VAO:dd/MM/yyyy HH:mm:ss}, ngày vào nội trú:{File.NGAY_VAO_NOI_TRU:dd/MM/yyyy HH:mm:ss}, ngày ra viện:{File.NGAY_RA:dd/MM/yyyy HH:mm:ss}\n" +
                            $"Tổng số ngày giường tại XML: {sumNgayGiuong} $$$$$ công thức tính ngày giường: {ngayGiuong}, Đề nghị kiểm tra lại";
                    if (sumNgayGiuong != ngayGiuong)
                    {
                        //3708	3	XML1	MA_BN	[3176] Bệnh nhân nằm nội trú nhưng không kê giường Bệnh
                        if (sumNgayGiuong == 0)
                        {
                            RaiseError(3708, msg.Replace("$$$$$", "khác với"));
                        }
                        else
                        {
                            foreach (var xml3 in allGiuongs)
                            {
                                if (sumNgayGiuong > ngayGiuong)
                                {
                                    xml3.RaiseError(439, msg.Replace("$$$$$", "lớn hơn"));
                                }

                                if (sumNgayGiuong < ngayGiuong)
                                {
                                    xml3.RaiseError(440, msg.Replace("$$$$$", "nhỏ hơn"));
                                }

                                //3690	4	XML3	MA_DICH_VU	[3176] Hòa Bình: Tổng số ngày giường nhỏ hơn Hướng dẫn thông tư 39 BYT
                                //3691    4   XML3 MA_DICH_VU[3176] Hòa Bình: Tổng số ngày giường lớn hơn Hướng dẫn thông tư 39 BYT
                                if (sumNgayGiuong > ngayGuuong3176)
                                {
                                    xml3.RaiseError(3691, msg.Replace("$$$$$", "lớn hơn"));
                                }
                                if (sumNgayGiuong < ngayGuuong3176)
                                {
                                    xml3.RaiseError(3690, msg.Replace("$$$$$", "nhỏ hơn"));
                                }
                            }
                        }
                    }
                }
            }

            //2500	3	XML1	MA_DOITUONG_KCB      [130] Mã đối tượng KCB là 9, không thanh toán BH y tế
            if (File.MA_DOITUONG_KCB == "9" && File.T_BHTT != 0)
            {
                RaiseError(2500, $"Bệnh nhân có mã đối tượng: {File.MA_DOITUONG_KCB}|{ServiceConstants.GetValue(ServiceConstants.MaDoiTuongKCB, File.KET_QUA_DTRI.ToString())}, Đối tượng không thanh toán BHYT");
            }

