                var xml05Info = File.XML05s.Where(x => x.HOI_CHAN != null && Uti.StrExists(x.HOI_CHAN.ToLower(), true, "chuyển viện", "Chuyển BV", "Chuyển Bệnh viện", "chuyển")).ToList();
