            //Có MA_THE_BHYT -> Kiểm tra các thông tin liên quan: MA_THE_BHYT, MA_DKBD, GT_THE_TU, GT_THE_DEN, NAM_NAM_LIEN_TUC 
            if (Field(x => x.MA_THE_BHYT).NotEmpty())
            {
                //Linhist added 220926 - thêm độ dài 17
