                                $"có Tình trạng ra Viện:{File.MA_LOAI_RV}|{ServiceConstants.GetValue(ServiceConstants.Loairavien, File.MA_LOAI_RV.ToString())} " +
                                "nhưng không có thông tin Giấy ra viện tại XML7, Đề nghị kiểm tra lại. Căn cứ Quyết định 3176 và Quyết định 4750 Bộ Y tế"
                            );
                    }
                }

                //2470	4	XML1	MA_LOAI_KCB	[130] Bắt buộc phải nhập nội dung tóm tắt hồ sơ Bệnh án (XML8) với những loại KCB là 03, 04 và 06
                if (Field(x => x.MA_LOAI_KCB).HasValue("03", "04", "06"))
                {
                    RaiseError(File.XML08s?.Any() != true,
                        2470, $"Bệnh nhân có mã khám chữa bệnh: {File.MA_LOAI_KCB}|{ServiceConstants.GetValue(ServiceConstants.LoaiKhamBenh, (File.MA_LOAI_KCB ?? string.Empty).ToString())} " +
                            $"nhưng không có tóm tắt hồ sơ bệnh án tại XML8, Đề nghị kiểm tra lại. Căn cứ Quyết định 3176 và Quyết định 4750 Bộ Y tế"
                        );
                }

                if (Field(x => x.MA_LOAI_KCB).HasValue("02", "03", "04", "05", "06", "08", "09"))
                {
                    RaiseError(File.XML05s?.Any() != true,
                        3988, $"Bệnh nhân có mã khám chữa bệnh: {File.MA_LOAI_KCB}|{ServiceConstants.GetValue(ServiceConstants.LoaiKhamBenh, (File.MA_LOAI_KCB ?? string.Empty).ToString())} " +
                            $"nhưng không có thông tin Chi tiết diễn biến lâm sàng tại XML5, Đề nghị kiểm tra lại. Căn cứ Quyết định 3176 và Quyết định 4750 Bộ Y tế"
                        );
                }

                if (File.NGAY_RA != null && File.NGAY_VAO != null)
                {
                    //2188	4	XML1	NGAY_RA	[130] Thời gian khám bệnh từ lúc đến viện đến lúc ra viện nhỏ hơn 5 phút, cần kiểm tra
                    RaiseError((File.NGAY_RA.Value - File.NGAY_VAO.Value).TotalMinutes < 5,
                        2188, $"Bệnh nhân vào viện: {File.NGAY_VAO:dd/MM/yyyy HH:mm:ss}, ra viện:{File.NGAY_RA:dd/MM/yyyy HH:mm:ss}, thời gian nhỏ hơn 5 phút, cần kiểm tra lại");

                    if (File.SO_NGAY_DTRI != null)
                    {
                        //2023    XML1    SO_NGAY_DTRI    Chỉ ghi 0 nếu MA_LOAI_KCB có các mã "01", "07", "09"
                        if (Field(x => x.MA_LOAI_KCB).HasValue("01", "07", "09"))
