                            RaiseError(File.SO_NGAY_DTRI != songay,
                                    2024, $"Bệnh nhân có loại khám chữa bệnh: {File.MA_LOAI_KCB}|{ServiceConstants.GetValue(ServiceConstants.MaDoiTuongKCB, File.MA_DOITUONG_KCB)}" +
                                    $"\n Số ngày điều trị phải nhập là 0, Căn cứ Quyết định 4705 và Quyết định 3176 Bộ Y Tế"
                                );
                        }

                        else if (Field(x => x.MA_LOAI_KCB).HasValue("05"))
                        {
                            var songaydungT = File.XML02s.Where(x => x.LIEU_DUNG != null && x.MA_NHOM == 4);
