                                    if (LieuDung.TryParse(x2.LIEU_DUNG ?? string.Empty, x2.DON_VI_TINH ?? string.Empty, out var ld) != 0) continue;
                                    if ((ld?.SoNgay ?? 0) > countsongaydT)
                                    {
                                        countsongaydT = (int)(ld?.SoNgay ?? 0);
                                    }
                                }
                            }
                            
                            RaiseError(File.SO_NGAY_DTRI != countsongaydT, 2414);
