                            var songaydungDV = File.XML03s.Where(x => x.NGAY_TH_YL != null).Select(x => x.NGAY_TH_YL).OrderByDescending(g => g.GetValueOrDefault()).ToList();
                            var countsongaydT = 0;
                            if (songaydungDV.Any())
                            {
                                var dngay = DateTime.Now.Date.AddDays(10);
                                foreach (var ngay in songaydungDV)
                                {
                                    if (ngay.GetValueOrDefault().Date != dngay.Date)
                                    {
                                        countsongaydT++;
                                        dngay = ngay.GetValueOrDefault();
                                    }
                                }
                            }
                            RaiseError(File.SO_NGAY_DTRI != countsongaydT, 2415);
