                        RaiseError(2338);
                    }
                    else
                    {
                        //2336	2346	0	XML1	NGAY_TAI_KHAM	[130] Số lượng ngày tái khám không đúng với thông tin khai báo tại XML14
                        var ngaytk = (File.NGAY_TAI_KHAM ?? string.Empty).Split(';');
                        if (ngaytk.Length != File.XML14s.Count)
                        {
