                                if (DateTime.TryParseExact(ngay, new string[] { "yyyyMMdd", "yyyyMMddHHmm" }, CultureInfo.InvariantCulture, DateTimeStyles.None, out var dte))
                                {
                                    RaiseError(!xml.XML14s.Any(x => dte.Date == x.NGAY_HEN_KL?.Date), 2339);
                                    break;
                                }
                                else
                                {
                                    RaiseError(2339);
                                    break;
                                }
                            }
                        }
                    }
                }
                //2337    2347    0   XML1 NGAY_TAI_KHAM[130] Ngày tái khám bắt buộc phải nhập khi khai báo XML14
                else if (File.XML14s is not null && File.XML14s.Count > 0)
                {
                    RaiseError(2337);
                }
            }

            #endregion

            #region Kiểm tra mã bệnh, bác sĩ, khoa
            string[]? benhCHs = null;
            string[]? benhKTs = null;
            if (!string.IsNullOrWhiteSpace(File.MA_BENH_CHINH))
            {
                benhCHs = File.MA_BENH_CHINH.Split(';');
                foreach (var benh in benhCHs)
                {

                    //2090	4	XML1	MA_BENH_CHINH	[130] Mã bệnh chính phải là mã ICD10, không nhập thêm mã Bệnh YHCT
                    RaiseError(_dmYHCT.Any(x => x.YHDTCode == benh),
                            2090, $"Mã bệnh chính {benh} phải là mã ICD10, không phải mã bệnh YHCT");

