                    RaiseError(!_dmCHUNG.Any(x => x.LOAI == "ICDCHINH" && x.MA == benh),
                            2321, $"Bệnh nhân có Mã bệnh chính:{File.MA_BENH_CHINH}, Không nằm trong phụ lục ICD10 - Quyết định 4469 Bộ Y Tế");

                    //4087	3	XML1	MA_BENH_CHINH	[3176] TT06/2026 Mã Bệnh không được dùng làm bệnh chính, đề nghị kiểm tra lại
                    RaiseError(_dmCHUNG.Any(x => x.LOAI == "TT06/2026" && x.MA == "MAKOBENHCHINH" && Uti.CodeMatch(benh, x.TEN ?? string.Empty)),
                        4087, $"Mã Bệnh {benh} không được dùng làm bệnh chính, Theo thông tư 06/2026 của Bộ Y Tế");

                    //4088    3   XML1 MA_BENH_CHINH[3176] TT06 / 2026 Mã bệnh không khuyến khích dùng làm mã Bệnh chính, đề nghị kiểm tra lại
                    RaiseError(_dmCHUNG.Any(x => x.LOAI == "TT06/2026" && x.MA == "MAKOKKBENHCHINH" && Uti.CodeMatch(benh, x.TEN ?? string.Empty)),
