                    {
                        RaiseError(_dmCHUNG.Any(x => x.LOAI == "TT06/2026" && x.MA == "MAHOATV" && Uti.CodeMatch(benh, x.TEN ?? string.Empty)),
                            4091, $"Mã Bệnh {benh} không được sử dụng vì đây là mã bệnh mã hóa cho nguyên nhân tử vong, Theo thông tư 06/2026 của Bộ Y Tế");
                    }

                    if (File.GIOI_TINH != 2)
                    {
                        RaiseError(_dmCHUNG.Any(x => x.LOAI == "TT06/2026" && x.MA == "MABENHNU" && Uti.CodeMatch(benh, x.TEN ?? string.Empty)),
                            4093, $"Mã Bệnh {benh} không được sử dụng vì đây là mã bệnh cho bệnh nhân nữ giới, Theo thông tư 06/2026 của Bộ Y Tế");
                    }

