                        RaiseError(_dmCHUNG.Any(x => x.LOAI == "TT06/2026" && x.MA == "MABENHNAM" && Uti.CodeMatch(benh, x.TEN ?? string.Empty)),
                            4095, $"Mã Bệnh {benh} không được sử dụng vì đây là mã bệnh cho bệnh nhân nam giới, Theo thông tư 06/2026 của Bộ Y Tế");
                    }

