                    //Linhist added 070826
                    //4205	2	XML1	MA_BENH_CHINH	Bệnh nhân có mã bệnh ICD không phù hợp, mã ICD đang thuộc nhóm mã bệnh mạn tính dài ngày theo TT25/2025/TT-BYT
                    if (File.MA_LOAI_KCB == "01" || File.MA_LOAI_KCB == "02")
