                    var hasDVs = File.XML03s.Any(x => x.MA_NHOM == 1 || x.MA_NHOM == 2 || x.MA_NHOM == 3 || x.MA_NHOM == 8 || x.MA_NHOM == 14 || x.MA_NHOM == 15 || x.MA_NHOM == 16 || x.MA_NHOM == 18);
