                    //4125	2	XML1	MA_BENH_KT	[3176] Mã bệnh chính không nằm trong danh mục mã bệnh của TT06
                    if (_dmCHUNG.Any(x => x.LOAI == "TT06/2026" && x.MA == "MABENHCHUNG" && !Uti.CodeMatch(x.TEN ?? string.Empty, benh)))
                    {
                        RaiseError(4125, $"Mã Bệnh {benh} không nằm trong danh mục mã bệnh, Theo thông tư 06/2026 của Bộ Y Tế");
