                            RaiseError(2993, $"Bệnh nhân có Mã bệnh chính: {File.MA_BENH_CHINH}| Mã bệnh kèm theo:{File.MA_BENH_KT}\n" +
                                    $"Trong mã bệnh kèm theo có Mã bệnh: {bkt}, trùng với mã bệnh chính, không hợp lý về chuyên môn"
