            //Linhist added 030926
            //4217	2	XML1	MA_LOAI_KCB	Mã Loại KCB không phù hợp theo Quyết định số 1804/QĐ-BYT ngày 19/6/2026
            if (!string.IsNullOrEmpty(File.MA_LOAI_KCB))
