                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhsanphu"]),
                        1601, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Mã Bệnh Sản Phụ Khoa chỉ phù hợp với Phụ nữ từ 9 - 60. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
