                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhtreduoi2"]),
                        1627, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Trẻ Nhỏ chỉ phù hợp với Trẻ em từ 0 - 2 tuổi. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
                        );
                }
