            if (Info.TUOI_BN > 10d && _dmDacBiet.ContainsKey("benhtreduoi10"))
            {
                var mabenhinfo = Info.MA_BENH_ICD10.Split(";");
                foreach (var b in mabenhinfo)
                {
                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhtreduoi10"]),
                        1628, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Trẻ Lớn chỉ phù hợp với Trẻ em từ 0 - 10 tuổi. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
