            if ((Info.TUOI_BN < 8d || Info.TUOI_BN > 19d) && _dmDacBiet.ContainsKey("benhdaythi"))
            {
                var mabenhinfo = Info.MA_BENH_ICD10.Split(";");
                foreach (var b in mabenhinfo)
                {
                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhdaythi"]),
                        1632, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Tuổi Dậy Thì chỉ phù hợp với Thiếu niên từ 8 - 19 tuổi. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
                        );
                }
            }

            if (Info.TUOI_BN < 1d && _dmDacBiet.ContainsKey("benhtretren1"))
            {
                var mabenhinfo = Info.MA_BENH_ICD10.Split(";");
                foreach (var b in mabenhinfo)
                {
                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhtretren1"]),
                        1631, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Trẻ em chỉ phù hợp với Trẻ em trên 1 tuổi. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
                        );
                }
            }

            if (Info.TUOI_BN < 15d && _dmDacBiet.ContainsKey("benhlontren15"))
            {
                var mabenhinfo = Info.MA_BENH_ICD10.Split(";");
                foreach (var b in mabenhinfo)
                {
                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhlontren15"]),
                        1633, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Người Trưởng Thành chỉ phù hợp với Bệnh nhân trên 15 tuổi. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
                        );
                }
            }

            if (Info.TUOI_BN < 30d && _dmDacBiet.ContainsKey("benhlontren30"))
            {
                var mabenhinfo = Info.MA_BENH_ICD10.Split(";");
                foreach (var b in mabenhinfo)
                {
                    RaiseError(Uti.CodeMatch(b, _dmDacBiet["benhlontren30"]),
                        1634, $"Bệnh nhân {Info.TUOI_BN} tuổi có mã Bệnh:{b}| là bệnh dành riêng cho Người Lớn chỉ phù hợp với Bệnh nhân trên 30 tuổi. Đề nghị kiểm tra lại." +
                            $"\n Căn cứ Quyết định 4469 của Bộ Y Tế"
                        );
                }
            }

            RaiseError(!_dmCHUNG.Any(x => x.LOAI == "ICDOCHINH" && x.MA == File.MA_BENH_CHINH),
                2343, $"Bệnh nhân có Mã bệnh chính:{File.MA_BENH_CHINH}, Không nằm trong Phụ lục A2: Các mã bệnh sử dụng là bệnh chính - Quyết định 4469 Bộ Y Tế");

            //2365	0	XML1	MA_BENH_CHINH	[130] Bệnh mãn tính dài ngày, mỗi lần khám bệnh của Bệnh nhân không nhỏ hơn 30 ngày
            if (_dmDacBiet.ContainsKey("BenhManTinhDaiNgay"))
            {
                var mabenhs = _dmDacBiet["BenhManTinhDaiNgay"];
                var hoso30Ngays = await _hosoRepository.GetListAsync(x => x.XML01ID != File.XML01ID && x.IsDelete != true && x.MA_CSKCB == File.MA_CSKCB && x.MA_BN == File.MA_BN && x.MA_LK != File.MA_LK && x.NGAY_TTOAN != null && x.NGAY_TTOAN.Value.AddDays(30) <= File.NGAY_TTOAN, query => query.OrderBy(x => x.NGAY_TTOAN));
                var hscheck = hoso30Ngays.Where(x => Uti.CodeMatch(x.MA_BENH_CHINH ?? string.Empty, mabenhs) || (x.MA_BENH_KT != null && Uti.CodeMatch(x.MA_BENH_KT, mabenhs))).FirstOrDefault();
                if (hscheck != null)
                {
                    foreach (var mabenhInfor in Info.MA_BENH_ICD10.Split(";"))
                    {
                        RaiseError(Uti.CodeContain(mabenhInfor, _dmDacBiet["BenhManTinhDaiNgay"]),
                            2365, $"Bệnh nhân có mã bệnh mãn tính:{mabenhInfor}|, đã đi khám vào ngày:{hscheck.NGAY_VAO:dd/MM/yyyy HH:mm:ss}, khoảng cách: {(File.NGAY_TTOAN - hscheck.NGAY_TTOAN).GetValueOrDefault().TotalDays:F0}, chưa đủ 30 ngày. Kiểm tra lại");
                    }
                }
            }
            #endregion

            //4225	2	XML1	MA_LOAI_KCB	Phát sinh chi phí giường nội trú/giường ban ngày với bệnh nhân không điều trị nội trú/điều trị ban ngày
            if (File.MA_LOAI_KCB != "03")
            {
                var xNoiTru = File.XML03s.FirstOrDefault(x => x.MA_NHOM == 15);
                if (xNoiTru != null)
                {
                    RaiseError(true,
                            4225, $"Bệnh nhân có Mã loại KCB: {File.MA_LOAI_KCB}, Có phát sinh giường nội trú tại XML03 STT: {xNoiTru.STT} - Mã dịch vụ: {xNoiTru.MA_DICH_VU}");
                }
            }
            if (File.MA_LOAI_KCB != "04")
            {
                var xNoiTru = File.XML03s.FirstOrDefault(x => x.MA_NHOM == 14);
                if (xNoiTru != null)
                {
                    RaiseError(true,
                            4225, $"Bệnh nhân có Mã loại KCB: {File.MA_LOAI_KCB}, Có phát sinh giường nội trú ban ngày tại XML03 STT: {xNoiTru.STT} - Mã dịch vụ: {xNoiTru.MA_DICH_VU}");
                }
            }
        }
        catch (Exception ex)
        {
            var fullError = new StringBuilder();
            fullError.AppendLine($"❌ Validate130:XML1 lỗi tại MaBN: {File.MA_BN}, XML01ID: {File.XML01ID}, MaCSKCB: {File.MA_CSKCB}");
            fullError.AppendLine($"⏱️ Thời điểm: {DateTime.Now:dd/MM/yyyy HH:mm:ss}");
            fullError.AppendLine($"📄 Message: {ex.Message}");
            fullError.AppendLine($"📌 StackTrace: {ex.StackTrace}");
            WriteLog(fullError.ToString(), nameof(ValidateXML01));
        }

        return true;
    }
}
